INSERT INTO feature VALUES('project-manifest','modules','A package, its root and its manifest','packages','implemented','ordinary',NULL,'A package is its `package.gandr` at its root and the modules under the directory its model''s `sources` names, found by walking up from any path in it; `check`, `test` and `fmt` given a path in it, or none from inside it, work on the whole package, and `check` writes `package.gandr.toml` beside it from the package source''s `Package` model, a model of `std.build`''s `Gandr.Package`, its `name`, `version`, `authors`, `licence`, `documentation` and `endpoint`, and the modules its sources make, each by its path, then a `[toolchain]` table of its `gandr`, `features` and `systems`, then, when its `spelling` names one, a `[presentation]` table, the table the user''s configuration file writes, rewrites it when the model changes and refuses a hand edit as drift; the line it prints for each manifest carries the package''s address, which the file does not. A language server opened on a package writes in the spelling its manifest''s `[presentation]` table names, over the user''s configuration and under the editor''s own setting. A source names a module of its package by its path, `import text.greet ;` reading the file `text/greet.gandr` beside the package source and binding it qualified, `text.greet.greeting`, as a term and as a type; a source in no package is its own root module. A type reads through a module path of any length, `a.b.c.Token`, as a term does. A list after the address and its alias, `import text.greet (greeting) ;`, binds the names it lists by their own names as well; an unaliased quoted import with a list binds only those, and a listed name its module does not declare, or keeps private, refuses the importing source. A workspace is the packages its `workspace.gandr` names, found by walking up from any directory below it: not a package, it states what its members share as a model of `Gandr.Workspace`, which each member''s package source imports, and names its members by a `pub def members : List(String)`, each a directory rooting a package; `check`, `test` and `fmt` given its directory, or none from it outside every package, work on its source and every member, and `check` writes each member''s `package.gandr.toml` from that member''s own model, and `workspace.gandr.toml` beside the workspace''s source from its `Workspace` model: its `version`, the members its `members` names and its `[toolchain]` table. `Gandr.Package` and `Gandr.Workspace` share their `version` and their toolchain constraints through the theory `Project` they include, which joins `Versioned` and `Toolchain` once.','surface-dispatcher surface-driver surface-lowering surface-grammar surface-format surface-lsp','corpus/model/projects/workspace.gandr corpus/model/projects/hello/package.gandr corpus/model/projects/hello/src/text/greet.gandr corpus/model/projects/tools/package.gandr crates/surface-dispatcher/tests/package.rs crates/surface-driver/tests/cli.rs crates/surface-lowering/tests/namespace.rs crates/surface-lsp/src/server.rs::server::tests::a_project_s_spelling_outranks_the_user_s_and_yields_to_the_editor_s_3135 corpus/ledger/features/project-manifest.gandr','corpus/ledger/features/project-manifest.gandr',NULL);
